sys_variable_value.value:
(function execute(inputs, outputs) {
    var rangesAlarm = JSON.parse(inputs.ranges_alarm_json);
    outputs.result = inputs.certificate.subject_common_name;
    for (var i in rangesAlarm) {
        var range = rangesAlarm[i];
        // outputs.result += "Checando " + JSON.stringify(range) + '\n';
        if (inputs.certificate.valid_to >= range.TS_Inicio
            && inputs.certificate.valid_to <= range.TS_Fim) {
            outputs.result += " Gerar alarme ";
            outputs.certificate = inputs.certificate;
            outputs.event_type = range.Tipo_Expira;
            break;
        } else {
            outputs.result += " Não gera alarme ";
        }
        outputs.result += "Expirando em " + 
            range.TS_Inicio +
            " Validade " + inputs.certificate.valid_from +
            ' - ' + inputs.certificate.valid_to + '\n';
    }
    // gs.info("EDX CertMgmt check expiration - " + outputs.result);
})(inputs, outputs);

