sys_variable_value.value:
(function execute(inputs, outputs) {
    if (inputs.ranges_alarm_json) {
        outputs.ranges_alarm_json = inputs.ranges_alarm_json;
        return;
    }
    var today = new GlideDateTime();

    var beginOfDay = new GlideDateTime(today.getDate() + " 00:00:00");
    var endOfDay = new GlideDateTime(today.getDate() + ' 23:59:59');

    var prazos = [30];
    var ranges_alarm = [];
    for (var i in prazos) {
        var expiraInicio = new GlideDateTime(beginOfDay);
        expiraInicio.addDaysLocalTime(prazos[i]);
        var expiraFim = new GlideDateTime(endOfDay);
        expiraFim.addDaysLocalTime(prazos[i]);

        ranges_alarm.push({
            TS_Inicio: expiraInicio,
            TS_Fim: expiraFim,
            Tipo_Expira: prazos[i] == 0 ? "expired" : "expiring"
        })
    }
    outputs.ranges_alarm_json = JSON.stringify(ranges_alarm);
})(inputs, outputs);

